export const AI_READINESS_PILLARS = [
  "Strategy",
  "Data",
  "Technology",
  "Talent",
  "Governance",
] as const

export type AiReadinessPillar = (typeof AI_READINESS_PILLARS)[number]

export type AiReadinessQuestion = {
  id: number
  pillar: AiReadinessPillar
  text: string
  options: ReadonlyArray<{
    label: string
    score: 1 | 2 | 3 | 4
  }>
}

export type AiReadinessAnswers = Record<number, number>

export type PillarMaturity = "Foundation" | "Developing" | "Strong"

export type PillarResult = {
  pillar: AiReadinessPillar
  rawScore: number
  score: number
  maturity: PillarMaturity
  insight: string
  action: string
}

export type AiReadinessStage = {
  name: "Foundation" | "Emerging" | "Operational" | "Advanced"
  eyebrow: string
  description: string
}

export type RoadmapStep = {
  period: "First 30 days" | "Days 31–60" | "Days 61–90"
  title: string
  description: string
  deliverable: string
}

export type AiReadinessResult = {
  rawScore: number
  score: number
  stage: AiReadinessStage
  summary: string
  pillarResults: PillarResult[]
  strongest: PillarResult
  priority: PillarResult
  roadmap: RoadmapStep[]
}

