function normalizeScore(rawScore: number, questionCount: number) {
  const minimum = questionCount
  const range = questionCount * 3
  return Math.round(((rawScore - minimum) / range) * 100)
}

function getGuidance(pillar: AiReadinessPillar, score: number) {
  if (score < 40) {
    return {
      maturity: "Foundation" as const,
      ...PILLAR_GUIDANCE[pillar].foundation,
    }
  }

  if (score < 70) {
    return {
      maturity: "Developing" as const,
      ...PILLAR_GUIDANCE[pillar].developing,
    }
  }

  return {
    maturity: "Strong" as const,
    ...PILLAR_GUIDANCE[pillar].strong,
  }
}

function createRoadmap(priority: PillarResult, secondPriority: PillarResult): RoadmapStep[] {
  return [
    {
      period: "First 30 days",
      title: `Create the ${priority.pillar.toLowerCase()} baseline`,
      description: priority.action,
      deliverable: `A named owner, current-state evidence, and one measurable ${priority.pillar.toLowerCase()} target.`,
    },
    {
      period: "Days 31–60",
      title: `Remove the next ${secondPriority.pillar.toLowerCase()} constraint`,
      description: secondPriority.action,
      deliverable: `A documented operating change that raises ${secondPriority.pillar.toLowerCase()} readiness for the pilot.`,
    },
    {
      period: "Days 61–90",
      title: "Run one measured, controlled pilot",
      description:
        "Launch a contained workflow with a business owner, baseline metric, human review point, risk log, and weekly learning review.",
      deliverable:
        "A go, refine, or stop decision backed by value, quality, adoption, cost, and risk evidence.",
    },
  ]
}

export function calculateAiReadiness(answers: AiReadinessAnswers): AiReadinessResult {
  const missingQuestion = AI_READINESS_QUESTIONS.find((question) => {
    const score = answers[question.id]
    return !Number.isInteger(score) || score < 1 || score > 4
  })

  if (missingQuestion) {
    throw new Error(`Question ${missingQuestion.id} requires an answer from 1 to 4.`)
  }

  const rawScore = AI_READINESS_QUESTIONS.reduce(
    (total, question) => total + answers[question.id],
    0,
  )
  const score = normalizeScore(rawScore, AI_READINESS_QUESTIONS.length)
  const stage = STAGES.find((entry) => score <= entry.max)?.stage ?? STAGES[STAGES.length - 1].stage

  const pillarResults = AI_READINESS_PILLARS.map((pillar) => {
    const questions = AI_READINESS_QUESTIONS.filter((question) => question.pillar === pillar)
    const pillarRawScore = questions.reduce(
      (total, question) => total + answers[question.id],
      0,
    )
    const pillarScore = normalizeScore(pillarRawScore, questions.length)

    return {
      pillar,
      rawScore: pillarRawScore,
      score: pillarScore,
      ...getGuidance(pillar, pillarScore),
    }
  })

  const ranked = [...pillarResults].sort((a, b) => a.score - b.score)
  const priority = ranked[0]
  const secondPriority = ranked[1]
  const strongest = ranked[ranked.length - 1]

  return {
    rawScore,
    score,
    stage,
    pillarResults,
    strongest,
    priority,
    summary: `${stage.description} ${strongest.pillar} is currently your strongest pillar, while ${priority.pillar} is the most important constraint to address next.`,
    roadmap: createRoadmap(priority, secondPriority),
  }
}

export function buildAnswerRows(answers: AiReadinessAnswers) {
  return AI_READINESS_QUESTIONS.map((question) => {
    const score = answers[question.id]
    const option = question.options.find((item) => item.score === score)

    return {
      question_id: question.id,
      pillar: question.pillar,
      question: question.text,
      answer: option?.label ?? "",
      score,
    }
  })
}
